const PARTNER_STORE_KEY='sprechraumPartnerNetwork';
let partnerStore={visible:false,friends:['dilan'],requests:[],groups:[],chats:{},blocked:[],reported:[],activeChat:null,room:null},partnerMediaStream=null;
function loadPartnerStore(){try{partnerStore={...partnerStore,...JSON.parse(localStorage.getItem(PARTNER_STORE_KEY)||'{}')}}catch{}savePartnerStore()}
function savePartnerStore(){localStorage.setItem(PARTNER_STORE_KEY,JSON.stringify({...partnerStore,room:null,activeChat:null}))}
const partnerById=id=>PARTNER_PROFILES.find(x=>x.id===id);
const purposeLabel=x=>({exam:'Sınav partneri',practice:'Konuşma pratiği',daily:'Günlük konuşma'}[x]||x);
function partnerCard(p){const friend=partnerStore.friends.includes(p.id),sent=partnerStore.requests.includes(p.id);return `<article class="partner-card ${p.online?'online':''}"><div class="partner-card-head"><span class="partner-photo">${escapeHtml(studentInitials(p.name))}</span><span><b>${escapeHtml(p.name)} ${p.verified?'✓':''}</b><small>${escapeHtml(p.city)} · ${p.age} yaş</small></span><em class="partner-level">${escapeHtml(p.level)}</em></div><div class="partner-purpose">${p.goals.map(x=>`<span>${escapeHtml(purposeLabel(x))}</span>`).join('')}</div><p>${escapeHtml(p.bio)}</p><div class="partner-meta"><span>Sınav<b>${escapeHtml(p.exam)} · ${escapeHtml(p.examDate)}</b></span><span>Diller<b>${escapeHtml(p.languages.slice(0,2).join(', '))}</b></span><span>Uygunluk<b>${escapeHtml(p.availability)}</b></span><span>Durum<b>${p.online?'Şimdi çevrimiçi':'Bugün aktifti'}</b></span></div><div class="partner-card-actions"><button data-partner-profile="${p.id}">Profili gör</button>${friend?`<button class="sent" data-partner-chat="${p.id}">Mesaj</button><button class="primary-action" data-partner-practice="${p.id}">Pratik</button>`:`<button class="primary-action ${sent?'sent':''}" data-partner-request="${p.id}">${sent?'İstek gönderildi':'İstek gönder'}</button>`}</div></article>`}
function renderPartnerDiscovery(){if(!$('#partnerCatalog'))return;const q=$('#partnerSearch').value.trim().toLocaleLowerCase('tr-TR'),level=$('#partnerLevel').value,goal=$('#partnerGoal').value,exam=$('#partnerExam').value,lang=$('#partnerLanguage').value;const result=PARTNER_PROFILES.filter(p=>!partnerStore.blocked.includes(p.id)&&(!q||`${p.name} ${p.city} ${p.languages.join(' ')}`.toLocaleLowerCase('tr-TR').includes(q))&&(!level||p.level===level)&&(!goal||p.goals.includes(goal))&&(!exam||p.exam===exam)&&(!lang||p.languages.includes(lang)));$('#partnerResultCount').textContent=result.length;$('#partnerCatalog').innerHTML=result.length?result.map(partnerCard).join(''):'<div class="theme-loading">Filtrelerine uygun aktif partner bulunamadı.</div>';updatePartnerVisibility()}
function updatePartnerVisibility(){const b=$('#partnerVisibility');if(!b)return;b.classList.toggle('on',partnerStore.visible);b.querySelector('em').textContent=partnerStore.visible?'Açık':'Kapalı'}
function openPartnerProfile(id){const p=partnerById(id),friend=partnerStore.friends.includes(id);if(!p)return;$('#partnerProfileContent').innerHTML=`<div class="partner-profile-cover"></div><div class="partner-profile-main"><span class="partner-photo">${escapeHtml(studentInitials(p.name))}</span><h2>${escapeHtml(p.name)} ${p.verified?'✓':''}</h2><small>${escapeHtml(p.city)} · ${p.level} Almanca · ${p.online?'Şimdi çevrimiçi':'Bugün aktifti'}</small><div class="partner-purpose">${p.goals.map(x=>`<span>${escapeHtml(purposeLabel(x))}</span>`).join('')}</div><p>${escapeHtml(p.bio)}</p><div class="partner-profile-grid"><div><span>Gireceği sınav</span><b>${escapeHtml(p.exam)} ${escapeHtml(p.level)}</b></div><div><span>Sınav tarihi</span><b>${escapeHtml(p.examDate)}</b></div><div><span>Konuştuğu diller</span><b>${escapeHtml(p.languages.join(', '))}</b></div><div><span>Uygun zaman</span><b>${escapeHtml(p.availability)}</b></div></div><div class="partner-profile-actions">${friend?`<button data-partner-chat="${p.id}">Mesaj gönder</button><button class="primary-action" data-partner-practice="${p.id}">Sınav pratiği yap</button>`:`<button class="primary-action" data-partner-request="${p.id}">Arkadaşlık isteği gönder</button>`}</div><div class="partner-danger-actions"><button type="button" data-partner-report="${p.id}">◇ Profili bildir</button><button type="button" data-partner-block="${p.id}">⊘ Engelle</button></div></div>`;$('#partnerProfileDialog').showModal()}
function reportPartner(id){if(!partnerStore.reported.includes(id))partnerStore.reported.push(id);savePartnerStore();$('#partnerProfileDialog').close();toast('Profil inceleme listesine alındı. Gerçek sürümde moderasyon ekibine iletilir.')}
function blockPartner(id){if(!partnerStore.blocked.includes(id))partnerStore.blocked.push(id);partnerStore.friends=partnerStore.friends.filter(x=>x!==id);savePartnerStore();$('#partnerProfileDialog').close();renderPartnerHub();toast('Profil engellendi ve listelerinden kaldırıldı.')}
function addFriend(id){if(!partnerStore.friends.includes(id))partnerStore.friends.push(id);if(!partnerStore.requests.includes(id))partnerStore.requests.push(id);savePartnerStore();renderPartnerDiscovery();renderFriends();$('#partnerProfileDialog').open&&$('#partnerProfileDialog').close();toast('İstek gönderildi · demo eşleşmesinde kabul edildi.')}
function renderFriends(){if(!$('#friendList'))return;const friends=partnerStore.friends.map(partnerById).filter(Boolean);$('#friendCount').textContent=friends.length;$('#friendList').innerHTML=friends.length?friends.map(p=>`<article class="friend-row"><span class="partner-photo">${escapeHtml(studentInitials(p.name))}</span><span><b>${escapeHtml(p.name)} · ${p.level}</b><small>${escapeHtml(p.city)} · ${p.online?'çevrimiçi':'çevrimdışı'}</small></span><div class="friend-row-actions"><button data-partner-chat="${p.id}">Mesaj</button><button data-partner-audio="${p.id}">Sesli ara</button><button data-partner-video="${p.id}">Görüntülü ara</button><button data-partner-practice="${p.id}">Sınav pratiği</button></div></article>`).join(''):'<div class="theme-loading">Henüz arkadaşın yok. Partner arama bölümünden istek gönderebilirsin.</div>';$('#friendActivity').innerHTML=friends.length?`<b>${friends.length} çalışma partnerin hazır</b><button data-partner-practice="${friends[0].id}">▶ ${escapeHtml(friends[0].name)} ile sınav pratiği</button><button data-partner-chat="${friends[0].id}">Mesajları aç</button>`:'<small>Önce bir partnerle eşleş.</small>'}
function openPartnerChat(id){const p=partnerById(id);if(!p)return;partnerStore.activeChat=id;partnerStore.chats[id] ||= [{from:'them',text:`Hallo ${currentStudent()?.name||''}! Wollen wir diese Woche zusammen Deutsch üben?`}];$('#chatPartnerName').textContent=p.name;renderPartnerChat();$('#partnerChatDialog').showModal()}
function renderPartnerChat(){const list=partnerStore.chats[partnerStore.activeChat]||[];$('#partnerChatStream').innerHTML=list.map(x=>`<div class="partner-chat-message ${x.from==='me'?'me':''}">${escapeHtml(x.text)}</div>`).join('');$('#partnerChatStream').scrollTop=$('#partnerChatStream').scrollHeight}
function sendPartnerChat(){const input=$('#partnerChatInput'),text=input.value.trim(),id=partnerStore.activeChat;if(!text||!id)return;partnerStore.chats[id].push({from:'me',text});input.value='';renderPartnerChat();savePartnerStore();setTimeout(()=>{partnerStore.chats[id].push({from:'them',text:'Ja, gerne! Welche Prüfungsthemen möchtest du üben?'});renderPartnerChat();savePartnerStore()},500)}
function renderGroups(){if(!$('#groupList'))return;$('#groupList').innerHTML=partnerStore.groups.length?partnerStore.groups.map((g,i)=>`<article class="group-card"><h4>${escapeHtml(g.name)}</h4><p>${escapeHtml(g.goal)} · ${g.members.length+1} üye</p><div class="group-members"><i>${escapeHtml(studentInitials(currentStudent()?.name))}</i>${g.members.map(id=>`<i>${escapeHtml(studentInitials(partnerById(id)?.name))}</i>`).join('')}</div><button data-group-open="${i}">Grup sohbetini aç</button></article>`).join(''):'<div class="theme-loading">Henüz grubun yok. Arkadaşlarını aynı çalışma grubunda birleştirebilirsin.</div>'}
function openGroupDialog(){const friends=partnerStore.friends.map(partnerById).filter(Boolean);$('#groupFriendChoices').innerHTML='<legend>Arkadaşlarını seç</legend>'+friends.map(p=>`<label><input type="checkbox" value="${p.id}"> ${escapeHtml(p.name)} · ${p.level}</label>`).join('');$('#groupName').value='';$('#groupDialog').showModal()}
function saveGroup(){const name=$('#groupName').value.trim(),members=$$('#groupFriendChoices input:checked').map(x=>x.value);if(!name||!members.length){toast('Grup adı yaz ve en az bir arkadaş seç.');return}partnerStore.groups.push({name,members,goal:$('#groupGoal').value,createdAt:new Date().toISOString()});savePartnerStore();$('#groupDialog').close();renderGroups();toast('Çalışma grubu oluşturuldu.')}
function setPartnerTab(tab){$$('[data-partner-tab]').forEach(x=>x.classList.toggle('active',x.dataset.partnerTab===tab));$$('[data-partner-panel]').forEach(x=>x.classList.toggle('active',x.dataset.partnerPanel===tab));$('#partnerRoom').hidden=true;if(tab==='friends')renderFriends();if(tab==='groups')renderGroups()}
function roomHintFor(task=''){const l=task.toLowerCase();if(/geschenk/.test(l))return 'Ich schlage vor, dass wir zusammen ein Geschenk kaufen. Was meinst du dazu?';if(/geld|kosten/.test(l))return 'Wir könnten von jeder Person zehn Euro einsammeln. Was meinst du dazu?';if(/verkehr/.test(l))return 'Wir könnten mit dem Auto fahren. Wie findest du das?';if(/wann|termin/.test(l))return 'Wie wäre es mit Samstag um zehn Uhr? Passt dir das?';if(/wo|treff/.test(l))return 'Wir könnten uns am Bahnhof treffen. Was meinst du dazu?';return 'Ich hätte eine Idee: Wir könnten das gemeinsam organisieren. Was meinst du dazu?'}
function openPartnerRoom(id,kind='practice'){const p=partnerById(id);if(!p)return;$('#partnerProfileDialog').open&&$('#partnerProfileDialog').close();$('#partnerChatDialog').open&&$('#partnerChatDialog').close();$$('[data-partner-panel]').forEach(x=>x.classList.remove('active'));partnerStore.room={partnerId:id,userRole:'A',started:false,themeId:state.themes[0]?.id||'',taskIndex:0,turns:[],kind};renderPartnerRoom();if(!state.themes.length)loadThemes().then(()=>{partnerStore.room.themeId=state.themes[0]?.id||'';renderPartnerRoom()})}
function renderPartnerRoom(){const room=partnerStore.room,p=partnerById(room?.partnerId),root=$('#partnerRoom');if(!room||!p)return;root.hidden=false;const theme=state.themes.find(x=>x.id===room.themeId)||state.themes[0],tasks=theme?.tasks||[],a=room.userRole==='A'?currentStudent()?.name:p.name,b=room.userRole==='B'?currentStudent()?.name:p.name;root.innerHTML=`<div class="room-head"><div><small>CANLI A/B PRATİK ODASI</small><h3>${escapeHtml(p.name)} ile sınav pratiği</h3></div><button data-room-close>Odayı kapat ×</button></div><div class="room-stage"><div class="room-partners"><div class="room-video" data-room-video="A"><span class="partner-photo">${escapeHtml(studentInitials(a))}</span>${room.userRole==='A'?'<video id="localPartnerVideo" autoplay muted playsinline></video>':''}<footer><span>Partner A · ${escapeHtml(a)} · Başlatır</span><button class="role-claim ${room.userRole==='A'?'active':''}" data-room-role="A">${room.userRole==='A'?'✓ Sen A’sın':'A olmak istiyorum'}</button></footer></div><div class="room-video" data-room-video="B"><span class="partner-photo">${escapeHtml(studentInitials(b))}</span>${room.userRole==='B'?'<video id="localPartnerVideo" autoplay muted playsinline></video>':''}<footer><span>Partner B · ${escapeHtml(b)}</span><button class="role-claim ${room.userRole==='B'?'active':''}" data-room-role="B">${room.userRole==='B'?'✓ Sen B’sin':'B olmak istiyorum'}</button></footer></div></div><div class="room-coach"><div class="room-theme-select"><select id="roomThemeSelect">${state.themes.map(x=>`<option value="${escapeHtml(x.id)}" ${x.id===room.themeId?'selected':''}>${escapeHtml(x.title)}</option>`).join('')}</select><button data-room-start>${room.started?'Yeniden başlat':'Clara ile başla'}</button></div>${theme?`<div class="room-task"><small>THEMA · ${room.taskIndex+1}/${Math.max(1,tasks.length)}</small><h4>${escapeHtml(theme.title)}</h4><p>${escapeHtml(theme.description)}</p><ul>${tasks.map((x,i)=>`<li class="${i<room.taskIndex?'done':i===room.taskIndex?'current':''}">${i<room.taskIndex?'✓ ':''}${escapeHtml(x)}</li>`).join('')}</ul></div>`:''}<div class="room-clara">${room.started?`Clara: ${room.taskIndex===0?`Aufgabe: ${theme?.description||''} Partner A beginnt. ${tasks[0]||''}`:`Jetzt sprechen wir über: ${tasks[room.taskIndex]||'Abschluss'}`}`:'Tema ve A/B rolünü seç. Başlattığında Clara görevi sesli okuyacak.'}</div><div class="room-dialogue">${room.turns.map(x=>`<div class="room-line"><b>${escapeHtml(x.role)}:</b> ${escapeHtml(x.text)}</div>`).join('')}</div>${room.started?`<div class="partner-chat-compose"><input id="roomTalkInput" placeholder="${room.turns.length%2===0?'Partner A':'Partner B'} konuşuyor…"><button type="button" data-room-send>Gönder</button></div>`:''}<div class="room-actions"><button class="room-hint" data-room-hint>✦ Clara’dan örnek cümle</button><button class="room-media" data-room-media="audio">Mikrofon</button><button class="room-media" data-room-media="video">Kamera</button><button class="room-finish" data-room-finish>Pratiği değerlendir</button></div><div id="roomPrivateHint"></div></div></div>`;if(partnerMediaStream){const video=$('#localPartnerVideo');if(video)video.srcObject=partnerMediaStream}}
function startRoom(){const room=partnerStore.room;if(!room)return;room.themeId=$('#roomThemeSelect').value;room.started=true;room.taskIndex=0;room.turns=[];renderPartnerRoom();const theme=state.themes.find(x=>x.id===room.themeId);speak(`Aufgabe: ${theme?.description||''}. Partner A beginnt. ${theme?.tasks?.[0]||''}`)}
function roomSend(){const input=$('#roomTalkInput'),text=input?.value.trim(),room=partnerStore.room;if(!text||!room)return;const role=room.turns.length%2===0?'A':'B';room.turns.push({role:`Partner ${role}`,text});if(room.turns.length%2===0){const theme=state.themes.find(x=>x.id===room.themeId);room.taskIndex=Math.min(room.taskIndex+1,Math.max(0,(theme?.tasks?.length||1)-1))}renderPartnerRoom()}
function showRoomHint(){const room=partnerStore.room,theme=state.themes.find(x=>x.id===room?.themeId),task=theme?.tasks?.[room.taskIndex]||'',hint=roomHintFor(task),box=$('#roomPrivateHint');box.innerHTML=`<div class="room-clara"><b>Yalnız senin ekranında:</b><br>${escapeHtml(hint)}</div>`;speak(hint)}
async function startPartnerMedia(kind){try{partnerMediaStream?.getTracks().forEach(x=>x.stop());partnerMediaStream=await navigator.mediaDevices.getUserMedia({audio:true,video:kind==='video'});const video=$('#localPartnerVideo');if(video)video.srcObject=partnerMediaStream;toast(kind==='video'?'Kamera hazır · gerçek uzaktan bağlantı için sunucu gerekir.':'Mikrofon hazır · gerçek uzaktan bağlantı için sunucu gerekir.')}catch{toast('Mikrofon veya kamera izni verilmedi.')}}
function finishPartnerRoom(){const room=partnerStore.room,theme=state.themes.find(x=>x.id===room?.themeId),total=theme?.tasks?.length||1,covered=Math.min(total,room.taskIndex+(room.turns.length?1:0)),interaction=Math.min(100,45+room.turns.length*8),taskScore=Math.round(covered/total*100),score=Math.round(interaction*.45+taskScore*.55);$('#roomPrivateHint').innerHTML=`<div class="room-evaluation"><b>Clara’nın ortak değerlendirmesi · ${score}/100</b><br>Partner A ve B, ${covered}/${total} görev maddesini konuştu. ${room.turns.length>=6?'Karşılıklı tepki ve akış güçlüydü.':'Birbirinizin önerisine daha fazla tepki verin ve partner soruları kullanın.'}<br><b>Sonraki hedef:</b> Her görevde öneri → partner sorusu → tepki → ortak karar.</div>`;recordLearningEvent('Canlı partner pratiği',{label:`${partnerById(room.partnerId)?.name} ile ${theme?.title||'sınav pratiği'}`,score})}
function renderPartnerHub(){renderPartnerDiscovery();renderFriends();renderGroups();updatePartnerVisibility()}
function applyLanguage(){document.documentElement.lang=state.uiLang;$$('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});if($('#themeSearch'))$('#themeSearch').placeholder=t('search');if($('#chatInput'))$('#chatInput').placeholder=t('write');renderModes();if(state.themes.length)renderThemeCatalog($('#themeSearch')?.value||'');if(state.exam)renderTask(state.exam.progress);if(state.view==='oral')renderOral();applyWordLanguage()}

function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.remove('show'),2400)}
function navigate(view){state.view=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={home:['B1 · DEUTSCH LERNEN',`Guten Morgen, ${currentStudent()?.name||'Schüler'}.`],practice:['B1 · GEMEINSAM ETWAS PLANEN',t('chooseTheme')],partners:['GEMEINSAM LERNEN','Sprechpartner finden'],exam:['MÜNDLICHE B1-PRÜFUNG',t('examPartsTitle')],oral:['PDF-GESTÜTZTES TRAINING',state.oral.part==='bild'?'Bildbeschreibung':'Sich vorstellen'],words:['B1 · WORTSCHATZ','Wortkarten'],grammar:['B1 · GRAMMATIK','Grammatik'],library:['PERSÖNLICHE QUELLEN','Bibliothek'],progress:['LETZTE 30 TAGE','Fortschritt']};$('#pageEyebrow').textContent=titles[view][0];$('#pageTitle').textContent=titles[view][1];$('.sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(view==='practice')openPractice();if(view==='partners')renderPartnerHub();if(view==='progress')renderProgress()}

function renderWeek(){const days=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];$('#weekRow').innerHTML=days.map((d,i)=>`<div class="day ${i<5?'done':''} ${i===6?'today':''}"><small>${d}</small><i>${i<5?'✓':i===6?'13':'·'}</i></div>`).join('')}
function themeImageStyle(index){const col=index%5,row=Math.floor(index/5);return `background-position:${col*25}% ${row*25}%`}
function renderThemeCatalog(filter=''){const catalog=$('#themeCatalog');const term=filter.trim().toLocaleLowerCase('de-DE');const themes=state.themes.filter(x=>!term||`${x.title} ${x.description} ${x.tasks.join(' ')}`.toLocaleLowerCase('de-DE').includes(term));catalog.innerHTML=themes.length?themes.map(x=>`<button class="theme-card" data-theme-id="${escapeHtml(x.id)}"><span class="theme-art" style="${themeImageStyle(x.imageIndex)}"></span><span class="theme-card-copy"><small>THEMA ${String(x.number).padStart(2,'0')} · ${x.tasks.length} AUFGABEN</small><b>${escapeHtml(x.title)}</b><em>${escapeHtml(x.description)}</em><span class="theme-mini-tasks">${x.tasks.slice(0,3).map(y=>`<i>${escapeHtml(y.replace(/\?+$/,''))}</i>`).join('')}</span></span><strong>${t('select')} <span>→</span></strong></button>`).join(''):'<div class="theme-loading">Kein passendes Thema gefunden.</div>'}
async function loadThemes(){try{const r=await fetch('/api/themes');if(!r.ok)throw new Error();state.themes=await r.json();renderThemeCatalog($('#themeSearch')?.value||'')}catch{$('#themeCatalog').innerHTML='<div class="theme-loading">Temalar yüklenemedi. Yerel sunucuyu kontrol edin.</div>'}}
function openPractice(){stopRecognition(false);window.speechSynthesis?.cancel();state.exam=null;state.selectedThemeId=null;$('#practiceLayout').hidden=true;$('#themePicker').hidden=false;$('#themeStartBtn').hidden=true;$('#coachNote').hidden=true;$('#pageTitle').textContent=t('chooseTheme');if(!state.themes.length)loadThemes();else renderThemeCatalog($('#themeSearch').value)}
function renderThemePreview(theme){$('#taskBrief').innerHTML=`<header><span><small>THEMA ${String(theme.number).padStart(2,'0')}</small><b>${escapeHtml(theme.title)}</b></span><em>PDF-AUFGABE</em></header><section><small>WAS SOLLEN SIE TUN?</small><p>${escapeHtml(theme.description)}</p></section><section><small>AUFGABEN</small><ul>${theme.tasks.map(x=>`<li><i>○</i><span>${escapeHtml(x)}</span></li>`).join('')}</ul></section><div class="dialogue-cycle"><b>${escapeHtml(t('taskRead'))}</b></div>`;$('#taskProgressLabel').textContent=`0 / ${theme.tasks.length+3} Aufgaben`;$('#chatStream').innerHTML='';$('#coachNote').hidden=true;$('#themeStartBtn').hidden=false;$('#themeStartBtn').textContent=`▶ ${t('startExam')}`}
function selectTheme(themeId){state.selectedThemeId=themeId;state.exam=null;const theme=state.themes.find(x=>x.id===themeId);$('#themePicker').hidden=true;$('#practiceLayout').hidden=false;$('#chatInput').disabled=true;$('#sendMessageBtn').disabled=true;$('#pageTitle').textContent=theme?.title||'Gemeinsam etwas planen';renderThemePreview(theme)}
