function renderModes(){const tabs=$('#modeTabs');if(tabs)tabs.innerHTML='';const descriptions={vorstellen:'Name, Herkunft, Wohnort, Familie, Beruf, Sprachen und Hobbys zusammenhängend vorstellen.',planen:'Mit einem Partner Vorschläge machen, reagieren und eine gemeinsame Entscheidung treffen.',bild:'Ein Bild in sechs Schritten beschreiben: Einleitung, Personen, Ort, Handlung, Details und Meinung.',problem:'Ein Problem erklären, Lösungen vorschlagen und gemeinsam entscheiden.'};$('#examModeGrid').innerHTML=MODES.map(m=>`<button class="mode-card mode-card-${m.id}" data-exam-part="${m.id}"><span class="mode-illustration">${modeIllustration(m.id)}</span><h3>${m.title}</h3><p>${descriptions[m.id]}</p><footer><b>${m.time}</b><span>${escapeHtml(m.source)} →</span></footer></button>`).join('')}
function renderTask(progress=state.exam?.progress){const m=MODES.find(x=>x.id===state.mode);if(!state.exam){$('#taskBrief').innerHTML=`<small>PDF-QUELLE · ${m?.time||''}</small><b>Wählen Sie zuerst ein Prüfungsthema.</b>`;return}const labels={tr:{who:'Clara başlıyor',what:'NE YAPILACAK?',cycle:'B1 konuşma döngüsü',steps:['Öneri yap','Partnerine sor','Tepki ver','Karar al'],tasks:'GÖREVLER · SIRAYLA TAMAMLA',phase:['Öneri + partnerine soru','Partnerin cevabına tepki'],count:'görev'},de:{who:'Clara beginnt',what:'WAS SOLLEN SIE TUN?',cycle:'B1-Gesprächsablauf',steps:['Vorschlag machen','Partner fragen','Reagieren','Entscheiden'],tasks:'AUFGABEN · DER REIHE NACH',phase:['Vorschlag + Partnerfrage','Auf Clara reagieren'],count:'Aufgaben'},en:{who:'Clara starts',what:'WHAT SHOULD YOU DO?',cycle:'B1 conversation cycle',steps:['Make a suggestion','Ask your partner','React','Decide'],tasks:'TASKS · COMPLETE IN ORDER',phase:['Suggestion + partner question','React to Clara'],count:'tasks'}}[state.uiLang]||{};const theme=state.exam.theme,items=progress?.items||theme.tasks.map(label=>({label,done:false,current:false}));$('#taskBrief').innerHTML=`<header><span><small>THEMA ${String(theme.number).padStart(2,'0')}</small><b>${escapeHtml(theme.title)}</b></span><em>ROLLE ${state.exam.studentRole} · ${escapeHtml(labels.who)}</em></header><section><small>${escapeHtml(labels.what)}</small><p>${escapeHtml(theme.description)}</p></section><div class="dialogue-cycle"><b>${escapeHtml(labels.cycle)}</b>${labels.steps.map((x,i)=>`<span>${escapeHtml(x)}</span>${i<labels.steps.length-1?'<i>→</i>':''}`).join('')}</div><section><small>${escapeHtml(labels.tasks)}</small><ul>${items.map(x=>`<li class="${x.done?'done':x.current?'current':''}"><i>${x.done?'✓':x.current?'→':'○'}</i><span>${escapeHtml(x.label)}${x.current&&x.steps===2?`<small>${x.phase===0?'1/2':'2/2'} · ${escapeHtml(labels.phase[x.phase||0])}</small>`:''}</span></li>`).join('')}</ul></section>`;$('#taskProgressLabel').textContent=`${progress?.done||0} / ${progress?.total||items.length} ${labels.count}`}
function resetChat(){const m=MODES.find(x=>x.id===state.mode);$('#chatStream').innerHTML='';addMessage('ai',openingFor(m.id),m.id==='planen'?'Merhaba İlyas. Birlikte piknik planlamak istiyoruz. Nerede yapalım?':'Sıra sende. Kısa ve net cümlelerle başlayabilirsin.');state.lastSpeech=openingFor(m.id);speak(state.lastSpeech)}
function openingFor(id){return {vorstellen:`Guten Tag, ${currentStudent()?.name||''}! Bitte stellen Sie sich kurz vor.`,planen:`Hallo ${currentStudent()?.name||''}. Wir möchten zusammen ein Picknick planen. Wo sollen wir es machen?`,problem:'Unser Kursraum ist nächste Woche geschlossen. Was können wir tun?',bild:'Schau dir die Aufgabe an. Was siehst du zuerst auf dem Bild?'}[id]}
function addMessage(role,text,tr=''){const d=document.createElement('div');d.className=`message ${role==='user'?'user':''}`;const you={tr:'Sen',de:'Sie',en:'You'}[state.uiLang];d.innerHTML=`<small>${role==='user'?you:selectedCharacter().name}</small><p>${escapeHtml(text)}</p>${tr?`<p class="translation">${escapeHtml(tr)}</p>`:''}`;$('#chatStream').appendChild(d);$('#chatStream').scrollTop=$('#chatStream').scrollHeight}
function addExample(text){if(!text)return;const d=document.createElement('div');d.className='example-suggestion';d.innerHTML=`<span>${escapeHtml(t('sayThis'))}</span><p>${escapeHtml(text)}</p>`;$('#chatStream').appendChild(d);$('#chatStream').scrollTop=$('#chatStream').scrollHeight}

async function beginSourceExam(themeId=state.selectedThemeId){stopRecognition(false);window.speechSynthesis?.cancel();state.exam=null;$('#themeStartBtn').hidden=true;$('#chatStream').innerHTML='';setVoiceState('thinking','Aufgabe wird vorbereitet');if(!state.started){state.started=true;state.seconds=0;$('#sessionTimer').textContent='00:00';state.timer=setInterval(()=>{state.seconds++;$('#sessionTimer').textContent=`${String(Math.floor(state.seconds/60)).padStart(2,'0')}:${String(state.seconds%60).padStart(2,'0')}`},1000)}try{const student=currentStudent(),res=await fetch('/api/exam/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'planen',themeId,language:state.uiLang,studentName:student.name,studentProfile:studentMemoryBrief()})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Quelle nicht gefunden');state.exam=data;$('#chatInput').disabled=false;$('#sendMessageBtn').disabled=false;renderTask(data.progress);$('#coachNote').hidden=true;const taskSpeech=`Aufgabe: ${data.theme.description} ${data.opening}`;addMessage('ai',`Aufgabe: ${data.theme.description}`);addMessage('ai',data.opening);if(data.example)addExample(data.example);state.lastSpeech=taskSpeech;speak(taskSpeech)}catch(error){renderThemePreview(state.themes.find(x=>x.id===themeId));addMessage('ai','Dieses Thema konnte nicht gestartet werden.',error.message);setVoiceState('','Quelle wird erwartet');toast('Thema konnte nicht gestartet werden.')}}

function systemPrompt(){const m=MODES.find(x=>x.id===state.mode);const sources=state.library.filter(x=>x.text).slice(-3).map(x=>x.text.slice(0,2200)).join('\n');return `Sen Clara adlı profesyonel telc/Goethe B1 Almanca sözlü sınav koçusun. Görev: ${m.title}. Kullanıcı Türkçe ana dilli. Cevabın yalnız geçerli JSON olsun: {"speak":"en fazla 2 kısa Almanca cümle","tr":"çok kısa Türkçe açıklama","feedback":"tek somut düzeltme veya ipucu"}. Öğrenciye konuşma alanı bırak, her turda tek soru sor. Seviyesi B1. ${sources?`Yüklenen kaynaklardan uygun olduğunda yararlan:\n${sources}`:''}`}
async function askLocal(text){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);try{if(!state.exam)throw new Error('source required');const res=await fetch('/api/exam/respond',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({sessionId:state.exam.sessionId,ollamaUrl:state.settings.url,model:state.settings.model,message:text,studentName:currentStudent()?.name,studentProfile:studentMemoryBrief()})});const data=await res.json();if(!res.ok||!data.speak)throw new Error(data.error||'model offline');return data}catch{return {speak:`${currentStudent()?.name||''}, bitte bleiben wir bei der Aufgabe aus deiner PDF. Versuche es noch einmal.`,tr:'Yalnız yüklenen kaynak içindeki sınav göreviyle devam edebiliriz.',feedback:'PDF temasındaki anahtar bilgileri kullan.',offline:true,redirected:true}}finally{clearTimeout(timeout)}}
function fallbackReply(text){const lower=text.toLowerCase();if(state.mode==='planen')return {speak:lower.includes('samstag')?'Samstag passt mir gut. Was sollen wir zum Picknick mitbringen?':'Das ist eine gute Idee. Passt dir Samstag um elf Uhr?',tr:'İyi bir fikir. Cumartesi saat on bir sana uyar mı?',feedback:'Öneriden sonra “Was meinst du dazu?” diye sor.'};if(state.mode==='vorstellen')return {speak:'Sehr gut. Warum lernen Sie Deutsch?',tr:'Çok iyi. Neden Almanca öğreniyorsunuz?',feedback:'Mesleğini “Ich arbeite als …” kalıbıyla söyleyebilirsin.'};if(state.mode==='problem')return {speak:'Das könnte funktionieren. Sollen wir online lernen?',tr:'Bu işe yarayabilir. Çevrim içi öğrenelim mi?',feedback:'Kibar öneri için “Wir könnten …” kullan.'};return {speak:'Gut beschrieben. Was machen die Personen im Hintergrund?',tr:'İyi betimledin. Arka plandaki kişiler ne yapıyor?',feedback:'Konum için “im Vordergrund / im Hintergrund” kalıplarını kullan.'}}
async function sendUser(text){text=text.trim();if(!text||$('#chatForm').classList.contains('busy'))return;if(!state.exam){toast(t('startExam'));return}learnStudentFacts(text);addMessage('user',text);$('#chatInput').value='';$('#chatInput').disabled=true;$('#sendMessageBtn').disabled=true;$('#chatForm').classList.add('busy');$('#chatInput').placeholder='Clara denkt nach…';setVoiceState('thinking','Antwort wird geprüft');const reply=await askLocal(text);addMessage('ai',reply.speak||'Bitte versuche es noch einmal.',state.uiLang==='tr'?(reply.tr||''):'');if(reply.example)addExample(reply.example);if(reply.progress)renderTask(reply.progress);$('#coachNote').hidden=true;state.lastSpeech=reply.speak;$('#chatForm').classList.remove('busy');$('#chatInput').disabled=!!reply.finished;$('#sendMessageBtn').disabled=!!reply.finished;$('#chatInput').placeholder=reply.finished?'Thema abgeschlossen · wähle ein neues Thema':t('write');if(reply.finished){recordLearningEvent('Gemeinsam etwas planen',{label:state.exam?.theme?.title||'Planlama teması'});toast('Tema tamamlandı ve gelişimine kaydedildi.')}if(reply.offline)toast('Lokales Modell verzögert; sichere Themenantwort verwendet.');speak(reply.speak);if(!reply.finished&&matchMedia('(pointer:fine)').matches)$('#chatInput').focus()}

function oralInfoHtml(part){const info={
  tr:{vorstellen:['Sich vorstellen nasıl işler?','Yaklaşık 45-60 saniye konuş. İsim, yaş, memleket, yaşadığın yer, aile, meslek, diller ve hobilerden bağlantılı cümlelerle söz et. Ardından Clara 1-2 kısa ek soru sorabilir.','und, aber, weil, außerdem, seit ve zurzeit bağlaçlarını kullan.'],bild:['Bildbeschreibung nasıl işler?','Yaklaşık 1-2 dakika konuş. Önce genel resmi söyle, sonra kişiler, yer, eylem ve ayrıntılara geç; en sonda tahmin ve kişisel görüş ekle.','En az iki konum ifadesi, bir tahmin ve bir kişisel görüş kullan. Görünmeyen uzun bir hikâye uydurma.']},
  de:{vorstellen:['Wie läuft „Sich vorstellen“ ab?','Sprechen Sie etwa 45-60 Sekunden über Name, Alter, Herkunft, Wohnort, Familie, Beruf, Sprachen und Hobbys. Danach kann Clara ein bis zwei kurze Zusatzfragen stellen.','Verbinden Sie Ihre Sätze mit und, aber, weil, außerdem, seit und zurzeit.'],bild:['Wie läuft die Bildbeschreibung ab?','Sprechen Sie etwa 1-2 Minuten. Nennen Sie zuerst das Thema, dann Personen, Ort, Handlungen und Details; ergänzen Sie am Ende eine Vermutung und Ihre Meinung.','Verwenden Sie mindestens zwei Ortsangaben, eine Vermutung und eine persönliche Meinung. Erfinden Sie keine lange Geschichte.']},
  en:{vorstellen:['How does “Sich vorstellen” work?','Speak for about 45-60 seconds about your name, age, origin, home, family, job, languages and hobbies. Clara may then ask one or two short follow-up questions.','Connect your sentences with und, aber, weil, außerdem, seit and zurzeit.'],bild:['How does Bildbeschreibung work?','Speak for about 1-2 minutes. Start with the general topic, then describe people, place, actions and details; finish with a guess and your opinion.','Use at least two position phrases, one guess and one personal opinion. Do not invent a long story.']}
  }[state.uiLang]||{};const [title,body,tip]=info[part]||[];return `<div class="oral-info"><h3>${escapeHtml(title||'')}</h3><p>${escapeHtml(body||'')}</p><ul><li>${escapeHtml(tip||'')}</li><li>PDF: Almanca B1 Sich vorstellen ve Bildbeschreibung Rehberi</li></ul></div>`}
function oralTop(part){return `<div class="oral-topline"><button class="oral-back" data-oral-back>← ${escapeHtml(t('back'))}</button><div class="oral-tools"><button data-oral-mode="learn" class="${state.oral.mode==='learn'?'active':''}">${escapeHtml(t('learnMode'))}</button><button data-oral-mode="exam" class="${state.oral.mode==='exam'?'active':''}">${escapeHtml(t('examMode'))}</button><button class="oral-info-button ${state.oral.showInfo?'active':''}" data-oral-info>ⓘ ${escapeHtml(t('info'))}</button></div></div><div class="oral-intro"><small>PDF-GESTÜTZTES B1-TRAINING</small><h2>${part==='bild'?'Bildbeschreibung':'Sich vorstellen'}</h2><p>${part==='bild'?'Einleitung · Personen · Ort · Handlung · Details · Vermutung / Meinung':'Name · Alter · Herkunft · Wohnort · Familie · Beruf · Sprachen · Freizeit · Ziel'}</p></div>${state.oral.showInfo?oralInfoHtml(part):''}`}
function openOralPart(part){stopOralRecording();state.oral={part,mode:'learn',picture:null,step:0,showInfo:false,lastFeedback:null,result:null,draft:''};navigate('oral');renderOral();if(part==='vorstellen')speak(VORSTELLEN_STEPS[0][1])}
function renderPictureCatalog(){return `${oralTop('bild')}<div class="picture-catalog">${PICTURES.map((p,i)=>`<button class="picture-card" data-picture-index="${i}"><span class="picture-thumb" style="background-position:${p.pos}"></span><span class="picture-card-copy"><small>BILD ${String(i+1).padStart(2,'0')}</small><b>${escapeHtml(p.title)}</b><p>${escapeHtml(p.hint)}</p></span><strong>${escapeHtml(t('select'))} →</strong></button>`).join('')}</div>`}
function oralCopy(key){const copy={tr:{completed:'Tamamlanan aşamalar',missing:'Şunları unuttun',nextTime:'Bir dahaki sefere şöyle diyebilirsin:',repeat:'Bu cevap eksik. Clara’nın örnek cümlesini tam olarak söyle ve yeniden gönder.',stop:'Kaydı bitir',recording:'Kayıt devam ediyor · bitirdiğinde kaydı durdur'},de:{completed:'Abgeschlossene Punkte',missing:'Diese Punkte fehlen noch',nextTime:'Beim nächsten Mal können Sie sagen:',repeat:'Diese Antwort ist unvollständig. Sprechen Sie Claras vollständigen Beispielsatz nach.',stop:'Aufnahme beenden',recording:'Die Aufnahme läuft · beenden Sie sie erst, wenn Sie fertig sind'},en:{completed:'Completed points',missing:'You forgot these points',nextTime:'Next time you can say:',repeat:'This answer is incomplete. Repeat Clara’s complete example sentence.',stop:'Stop recording',recording:'Recording continues · stop it when you are finished'},uk:{completed:'Виконані пункти',missing:'Ви пропустили ці пункти',nextTime:'Наступного разу можна сказати:',repeat:'Відповідь неповна. Повторіть повне речення Клари.',stop:'Зупинити запис',recording:'Запис триває · зупиніть його, коли закінчите'},ar:{completed:'النقاط المكتملة',missing:'لقد نسيت هذه النقاط',nextTime:'في المرة القادمة يمكنك أن تقول:',repeat:'الإجابة غير مكتملة. كرّر جملة كلارا الكاملة.',stop:'إيقاف التسجيل',recording:'التسجيل مستمر · أوقفه عند الانتهاء'},ku:{completed:'Beşên qedandî',missing:'Te van beşan ji bîr kir',nextTime:'Cara din tu dikarî bibêjî:',repeat:'Bersiv ne temam e. Hevoka Clara bi tevahî dubare bike.',stop:'Tomarkirinê rawestîne',recording:'Tomarkirin didome · dema tu qediya rawestîne'},sr:{completed:'Završene stavke',missing:'Ove stavke nedostaju',nextTime:'Sledeći put možeš reći:',repeat:'Odgovor nije potpun. Ponovi celu Klarinu rečenicu.',stop:'Zaustavi snimanje',recording:'Snimanje traje · zaustavi ga kada završiš'},bs:{completed:'Završene stavke',missing:'Ove stavke nedostaju',nextTime:'Sljedeći put možeš reći:',repeat:'Odgovor nije potpun. Ponovi cijelu Clarinu rečenicu.',stop:'Zaustavi snimanje',recording:'Snimanje traje · zaustavi ga kada završiš'}};return (copy[state.uiLang]||copy.en)[key]}
const VORSTELLEN_RULES=[
  {test:s=>/(guten tag|guten morgen|guten abend|hallo|grüß)/i.test(s)&&/(mein name ist|ich hei(?:ß|ss)e|ich bin\s+(?!\d+\s*jahre)[a-zäöüß]{2,})/i.test(s),example:'Guten Tag. Mein Name ist …'},
  {test:s=>/ich bin\s+\d{1,3}\s+jahre alt/i.test(s),example:'Ich bin … Jahre alt.'},
  {test:s=>/(ich komme(?: ursprünglich)? aus|ich bin in .+ geboren)/i.test(s),example:'Ich komme ursprünglich aus … und bin in … geboren.'},
  {test:s=>/(ich wohne in|ich lebe in|zurzeit wohne ich in|seit .+ lebe ich in)/i.test(s),example:'Zurzeit wohne ich in …'},
  {test:s=>/(ich bin (?:verheiratet|ledig|geschieden)|ich habe .{0,25}(?:kind|sohn|tochter)|meine familie)/i.test(s),example:'Ich bin … und habe …'},
  {test:s=>/(von beruf bin ich|ich arbeite als|zurzeit arbeite ich|ich mache eine ausbildung)/i.test(s),example:'Von Beruf bin ich …'},
  {test:s=>/(meine muttersprache ist|ich spreche|außerdem spreche ich)/i.test(s),example:'Meine Muttersprache ist … Außerdem spreche ich …'},
  {test:s=>/(in meiner freizeit|mein hobby ist|meine hobbys sind|ich (?:höre|lese|spiele|gehe|mache|koche|reise).{0,30}gern)/i.test(s),example:'In meiner Freizeit … ich gern …'},
  {test:s=>/(ich lerne deutsch,? weil|mein ziel ist)/i.test(s)&&/(vielen dank|das war|danke für)/i.test(s),example:'Ich lerne Deutsch, weil … Das war meine kurze Vorstellung. Vielen Dank.'}
];
function analyseVorstellenCoverage(text){const completed=[],missing=[];VORSTELLEN_RULES.forEach((rule,i)=>{if(rule.test(String(text)))completed.push(i);else missing.push({index:i,label:VORSTELLEN_STEPS[i][0],example:profileFactExample(i)||rule.example})});return {completed,missing}}
function coverageHtml(text,showMissing=false){const c=analyseVorstellenCoverage(text);return `<div class="oral-coverage" id="oralCoverageHint"><header><b>${escapeHtml(oralCopy('completed'))}</b><span>${c.completed.length} / ${VORSTELLEN_STEPS.length}</span></header>${showMissing&&c.missing.length?`<div class="oral-missing"><strong>${escapeHtml(oralCopy('missing'))}</strong><small>${escapeHtml(oralCopy('nextTime'))}</small>${c.missing.map(x=>`<p><b>${x.index+1}. ${escapeHtml(x.label)}</b><em>${escapeHtml(x.example)}</em></p>`).join('')}</div>`:''}</div>`}
function resultHtml(result){if(!result)return'';const missing=result.coverage?.missing||[];return `<div class="oral-result"><div class="oral-score"><b>${Number(result.score)||0}</b><span><strong>${escapeHtml(t('evaluation'))}</strong><br>${escapeHtml(result.summary||'')}</span></div>${missing.length?`<div class="oral-missing result-missing"><strong>${escapeHtml(oralCopy('missing'))}</strong><small>${escapeHtml(oralCopy('nextTime'))}</small>${missing.map(x=>`<p><b>${x.index+1}. ${escapeHtml(x.label)}</b><em>${escapeHtml(x.example)}</em></p>`).join('')}</div>`:''}${(result.sentences||[]).map(x=>`<div class="sentence-review ${x.status==='wrong'?'wrong':'correct'}">${x.status==='wrong'?`<del>${escapeHtml(x.original)}</del><ins>✓ ${escapeHtml(x.corrected||x.original)}</ins>`:`<ins>✓ ${escapeHtml(x.original)}</ins>`}${x.reason?`<small>${escapeHtml(x.reason)}</small>`:''}</div>`).join('')}</div>`}
function feedbackHtml(feedback){if(!feedback)return'';return `<div class="oral-result"><div class="sentence-review ${feedback.correct?'correct':'wrong'}">${feedback.correct?`<ins>✓ ${escapeHtml(feedback.feedback||t('good'))}</ins>`:`<del>${escapeHtml(feedback.original||'')}</del><ins>✓ ${escapeHtml(feedback.corrected||'')}</ins><small>${escapeHtml(feedback.feedback||t('needsWork'))}</small>`}</div></div>`}
function renderOral(){const root=$('#oralApp');if(!root||!state.oral.part)return;const part=state.oral.part;if(part==='bild'&&state.oral.picture===null){root.innerHTML=renderPictureCatalog();return}const steps=part==='bild'?BILD_STEPS:VORSTELLEN_STEPS,picture=part==='bild'?PICTURES[state.oral.picture]:null,step=Math.min(state.oral.step,steps.length-1),current=steps[step],exam=state.oral.mode==='exam',coverage=part==='vorstellen'?analyseVorstellenCoverage(state.oral.draft||''):null;const visuals=part==='bild'?`<div class="oral-visuals"><div class="oral-avatar"><img src="assets/clara-2d.svg" alt="Clara"><span><b>Clara</b><small>B1-Prüfungslehrerin</small></span></div><div class="oral-scene" style="background-position:${picture.pos}"></div><details><summary>${escapeHtml(t('description'))}</summary><p>${escapeHtml(picture.sample)}</p></details></div>`:`<div class="oral-visuals"><div class="oral-avatar"><img src="assets/clara-2d.svg" alt="Clara"><span><b>Clara</b><small>B1-Prüfungslehrerin</small></span></div><div class="oral-start-card"><h3>Ihre Vorstellung</h3><p>45-60 Sekunden · 8-10 verbundene Sätze</p><div class="profile-outline">${VORSTELLEN_STEPS.map((x,i)=>{const done=exam?coverage.completed.includes(i):i<state.oral.step,currentStep=!exam&&i===state.oral.step;return `<span data-profile-step="${i}" class="${done?'done':currentStep?'current':''}"><b>${done?'✓':i+1}</b>${escapeHtml(x[0])}</span>`}).join('')}</div><details><summary>${escapeHtml(t('description'))}</summary><p>${escapeHtml(VORSTELLEN_STEPS.map((_,i)=>profileFactExample(i)).join(' '))}</p></details></div></div>`;const prompt=exam?(part==='bild'?'Beschreiben Sie bitte das Bild vollständig. Sie haben etwa ein bis zwei Minuten Zeit.':'Stellen Sie sich bitte vollständig vor. Sie haben etwa 45 bis 60 Sekunden Zeit.'):current[1];const suggestion=part==='vorstellen'?profileFactExample(step):current[2];const coach=`<div class="oral-coach"><div class="oral-prompt"><small>${exam?'PRÜFUNGSAUFGABE':`SCHRITT ${step+1} / ${steps.length}`}</small><b>${escapeHtml(prompt)}</b><p>${exam?(part==='bild'?'Sprechen Sie zusammenhängend und senden Sie Ihre vollständige Bildbeschreibung erst am Ende.':'Starten Sie die Aufnahme, sprechen Sie vollständig und beenden Sie die Aufnahme erst selbst. Danach drücken Sie auf Auswertung.'):'Clara lässt Sie erst nach einem vollständigen, passenden Satz zum nächsten Schritt weiter.'}</p></div>${!exam?`<div class="oral-step-list">${steps.map((x,i)=>`<span class="${i<state.oral.step?'done':i===state.oral.step?'current':''}">${i<state.oral.step?'✓':i+1}. ${escapeHtml(x[0])}</span>`).join('')}</div><div class="oral-suggestion"><small>${escapeHtml(t('nextSuggestion'))}</small><p>${escapeHtml(suggestion)}</p></div>`:''}<textarea class="oral-transcript" id="oralTranscript" placeholder="${escapeHtml(t('write'))}">${escapeHtml(state.oral.draft||'')}</textarea>${exam&&part==='vorstellen'?coverageHtml(state.oral.draft||'',false):''}<div class="oral-actions"><button class="oral-mic ${oralRecording?'recording':''}" data-oral-mic>${oralRecording?'■ '+escapeHtml(oralCopy('stop')):'● '+escapeHtml(t('record'))}</button><button class="oral-submit" data-oral-submit>${escapeHtml(exam?t('evaluation'):t('send'))} →</button></div>${oralRecording?`<div class="oral-recording-note"><i></i>${escapeHtml(oralCopy('recording'))}</div>`:''}${feedbackHtml(state.oral.lastFeedback)}${resultHtml(state.oral.result)}</div>`;root.innerHTML=`${oralTop(part)}<div class="oral-workspace">${visuals}${coach}</div>`}
function selectPicture(index){state.oral.picture=Number(index);state.oral.step=0;state.oral.mode='learn';state.oral.lastFeedback=null;state.oral.result=null;renderOral();speak(BILD_STEPS[0][1])}
function simpleCorrection(text){let corrected=String(text).trim().replace(/\baufdem\b/gi,'Auf dem').replace(/\bder man\b/gi,'der Mann').replace(/\bdie man\b/gi,'der Mann').replace(/\btrinkt wasser\b/gi,'trinkt Wasser').replace(/\bich arbeite als eine ([A-ZÄÖÜa-zäöüß]+)/g,'ich arbeite als $1').replace(/\bweil ich arbeite hier\b/gi,'weil ich hier arbeite').replace(/\b(bild|mann|frau|kind|wasser|familie|park|vordergrund|hintergrund)\b/gi,w=>w.charAt(0).toUpperCase()+w.slice(1).toLowerCase());if(corrected)corrected=corrected.charAt(0).toUpperCase()+corrected.slice(1);return corrected}
async function callOralAI(system,message){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({ollamaUrl:state.settings.url,model:state.settings.model,system,message})});if(!res.ok)throw Error();return await res.json()}finally{clearTimeout(timer)}}
function shortAnswerValue(text){return String(text).trim().replace(/[.!?]+$/,'').replace(/^(hallo|guten tag|ich bin|ich heiße|mein name ist|ich wohne in|ich komme aus)\s+/i,'').trim()}
function dynamicVorstellenExample(step,text){const value=shortAnswerValue(text)||'…',n=(text.match(/\b\d{1,3}\b/)||[])[0];if(step===0)return /^(hallo|guten tag|guten morgen|guten abend)[.!]?$/i.test(text.trim())?profileFactExample(0):`Guten Tag. Mein Name ist ${value}.`;if(step===1)return `Ich bin ${n||currentStudent()?.age||'…'} Jahre alt.`;if(step===2)return `Ich komme aus ${value}.`;if(step===3)return `Ich wohne in ${value}.`;if(step===4){if(/verheiratet/i.test(text))return 'Ich bin verheiratet.';if(/ledig/i.test(text))return 'Ich bin ledig.';return profileFactExample(4)}if(step===5)return `Von Beruf bin ich ${value}.`;if(step===6)return `Meine Muttersprache ist ${value}. Außerdem spreche ich Deutsch.`;if(step===7)return `In meiner Freizeit ${/musik/i.test(text)?'höre ich gern Musik':'gehe ich gern spazieren'}.`;return profileFactExample(8)}
function validateVorstellenStep(step,text){const correct=VORSTELLEN_RULES[step].test(String(text));return {correct,original:text,corrected:correct?simpleCorrection(text):dynamicVorstellenExample(step,text),feedback:correct?t('good'):oralCopy('repeat')}}
async function analyseOralStep(text){const part=state.oral.part,steps=part==='bild'?BILD_STEPS:VORSTELLEN_STEPS,current=steps[Math.min(state.oral.step,steps.length-1)],language=LANGUAGE_NAMES[state.uiLang]||'English';if(part==='vorstellen')return validateVorstellenStep(state.oral.step,text);const system=`You are Clara, a strict but supportive German B1 speaking teacher. Current section: ${part}. Current step: ${current[0]}. Decide whether the student's German answer adequately answers the current question. Do not correct an understandable correct sentence. Output only JSON: {"correct":true,"feedback":"one natural sentence in ${language}","corrected":"German corrected sentence"}. If wrong, corrected must preserve the student's meaning.`;try{const out=await callOralAI(system,text),bad=/short|feedback|turkish|german|natural sentence/i.test(String(out.feedback||''));if(typeof out.correct==='boolean'&&!bad)return {...out,original:text}}catch{}const corrected=simpleCorrection(text),wrong=corrected!==text.trim()||text.trim().split(/\s+/).length<3;return {correct:!wrong,original:text,corrected,feedback:wrong?t('needsWork'):t('good')}}
function fallbackEvaluation(text,part){const sentences=(text.match(/[^.!?]+[.!?]?/g)||[]).map(x=>x.trim()).filter(Boolean),reviews=sentences.map(original=>{const corrected=simpleCorrection(original),wrong=corrected!==original;return {original,status:wrong?'wrong':'correct',corrected,reason:wrong?t('needsWork'):''}}),coverage=part==='vorstellen'?analyseVorstellenCoverage(text):null;const lower=text.toLowerCase(),checks=part==='bild'?[/auf dem bild|das bild zeigt/,/vordergrund|hintergrund|links|rechts/,/vielleicht|wahrscheinlich|vermutlich/,/ich finde|meiner meinung|erinnert mich/]:VORSTELLEN_RULES.map(x=>({test:x.test}));const completed=part==='vorstellen'?coverage.completed.length:checks.filter(r=>r.test(lower)).length,score=Math.max(25,Math.min(95,35+completed*6+Math.min(8,sentences.length*2)-reviews.filter(x=>x.status==='wrong').length*5)),summaries={tr:completed>=8?'Tanıtım anlaşılır ve büyük ölçüde tamamlandı.':'Tanıtım anlaşılır; aşağıdaki eksik aşamaları bir dahaki sefere ekle.',de:completed>=8?'Die Vorstellung ist verständlich und weitgehend vollständig.':'Die Vorstellung ist verständlich; ergänzen Sie beim nächsten Mal die fehlenden Punkte.',en:completed>=8?'The introduction is understandable and mostly complete.':'The introduction is understandable; add the missing points next time.'},summary=(summaries[state.uiLang]||summaries.en);return {score,summary,sentences:reviews,coverage}}
async function evaluateOral(text){const part=state.oral.part,picture=part==='bild'?PICTURES[state.oral.picture]:null,language=LANGUAGE_NAMES[state.uiLang]||'English',requirements=part==='bild'?'topic, people, place, actions, foreground/background or left/right, at least one guess, personal opinion':'name, age, origin, place of residence, family, profession, languages, hobbies, reason for learning German and closing',deterministic=fallbackEvaluation(text,part);if(deterministic.sentences.some(x=>x.status==='wrong'))return deterministic;const system=`You are a professional German B1 oral examiner. Evaluate the complete ${part==='bild'?'picture description':'self-introduction'} according to this checklist: ${requirements}. ${picture?`Picture topic: ${picture.title}. Visible scene guide: ${picture.sample}`:''} Return only JSON: {"score":0,"summary":"one natural sentence in ${language}","sentences":[{"original":"student sentence","status":"correct or wrong","corrected":"German correction","reason":"one short sentence in ${language}"}]}. Mark only genuine mistakes as wrong; preserve meaning; include every student sentence.`;try{const out=await callOralAI(system,text),joined=JSON.stringify(out),expected=(text.match(/[.!?]+/g)||[]).length||1,bad=/short (turkish|german|english)|natural sentence|incorrect -|needs to be/i.test(joined);if(Number.isFinite(Number(out.score))&&Number(out.score)>0&&Array.isArray(out.sentences)&&out.sentences.length>=Math.min(2,expected)&&!bad)return {...out,coverage:deterministic.coverage}}catch{}return deterministic}
async function handleOralSubmit(){const input=$('#oralTranscript'),text=input?.value.trim();if(!text)return;state.oral.draft=text;if(oralRecording)stopOralRecording();const button=$('[data-oral-submit]');button.disabled=true;button.textContent='Clara …';if(state.oral.mode==='exam'){state.oral.result=await evaluateOral(text);state.oral.lastFeedback=null;if(state.oral.part==='vorstellen')learnStudentFacts(text);recordLearningEvent(state.oral.part==='vorstellen'?'Sich vorstellen':'Bildbeschreibung',{label:state.oral.part==='vorstellen'?'Sich vorstellen · Prüfungsmodus':'Bildbeschreibung · Prüfungsmodus',score:state.oral.result.score});renderOral();return}const feedback=await analyseOralStep(text);state.oral.lastFeedback=feedback;if(feedback.correct){if(state.oral.part==='vorstellen')learnStudentFacts(text);const steps=state.oral.part==='bild'?BILD_STEPS:VORSTELLEN_STEPS;state.oral.draft='';if(state.oral.step<steps.length-1){state.oral.step++;renderOral();speak(steps[state.oral.step][1])}else{state.oral.result=fallbackEvaluation(text,state.oral.part);recordLearningEvent(state.oral.part==='vorstellen'?'Sich vorstellen':'Bildbeschreibung',{label:`${state.oral.part==='vorstellen'?'Sich vorstellen':'Bildbeschreibung'} · Öğretme modu`,score:state.oral.result.score});renderOral();speak(`Sehr gut, ${currentStudent()?.name||''}. Sie haben diesen Teil vollständig abgeschlossen.`)}}else{state.oral.draft='';renderOral();speak(feedback.corrected||'Bitte versuchen Sie es noch einmal.')}}
let oralRecognition=null,oralRecording=false,oralFinalTranscript='';
function updateOralRecordingButton(){const button=$('[data-oral-mic]');if(!button)return;button.classList.toggle('recording',oralRecording);button.textContent=oralRecording?`■ ${oralCopy('stop')}`:`● ${t('record')}`}
function stopOralRecording(){oralRecording=false;try{oralRecognition?.stop()}catch{}oralRecognition=null;updateOralRecordingButton()}
function beginOralRecognitionSession(){if(!oralRecording)return;const rec=new SR();oralRecognition=rec;rec.lang='de-DE';rec.continuous=true;rec.interimResults=true;rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const phrase=e.results[i][0].transcript.trim();if(e.results[i].isFinal)oralFinalTranscript+=`${phrase} `;else interim+=`${phrase} `}const value=`${oralFinalTranscript}${interim}`.trim(),input=$('#oralTranscript');state.oral.draft=value;if(input)input.value=value;updateVorstellenChecklist(value)};rec.onerror=e=>{if(['not-allowed','service-not-allowed','audio-capture'].includes(e.error)){oralRecording=false;renderOral();toast('Mikrofon izni gerekli.')}};rec.onend=()=>{oralRecognition=null;if(oralRecording)setTimeout(beginOralRecognitionSession,180);else updateOralRecordingButton()};try{rec.start()}catch{oralRecording=false;renderOral()}}
function recordOral(){if(!SR){toast('Spracherkennung wird in diesem Browser nicht unterstützt.');return}if(oralRecording){stopOralRecording();renderOral();return}oralFinalTranscript=($('#oralTranscript')?.value||state.oral.draft||'').trim();if(oralFinalTranscript)oralFinalTranscript+=' ';state.oral.result=null;oralRecording=true;renderOral();beginOralRecognitionSession()}
function updateVorstellenChecklist(text){if(state.oral.part!=='vorstellen')return;state.oral.draft=text;const coverage=analyseVorstellenCoverage(text);$$('[data-profile-step]').forEach((el,i)=>{const done=coverage.completed.includes(i);el.classList.toggle('done',done);el.querySelector('b').textContent=done?'✓':i+1});const hint=$('#oralCoverageHint');if(hint)hint.outerHTML=coverageHtml(text,false)}

const MOUTH_RIG={
  REST:{mouth:'M-25 2Q0 9 25 2Q0 15-25 2Z',lower:'M-23 4Q0 15 23 4Q0 11-23 4Z',teeth:0,tongue:0},
  A:{mouth:'M-26-1Q0-9 26-1Q29 31 0 34Q-29 31-26-1Z',lower:'M-25 3Q0 36 25 3Q0 29-25 3Z',teeth:.16,tongue:.78},
  E:{mouth:'M-32 0Q0-7 32 0Q0 20-32 0Z',lower:'M-30 4Q0 21 30 4Q0 16-30 4Z',teeth:.94,tongue:.15},
  I:{mouth:'M-35 2Q0-5 35 2Q0 14-35 2Z',lower:'M-33 5Q0 15 33 5Q0 12-33 5Z',teeth:.98,tongue:0},
  O:{mouth:'M-18-5Q0-14 18-5Q23 27 0 32Q-23 27-18-5Z',lower:'M-17 0Q0 34 17 0Q0 28-17 0Z',teeth:.05,tongue:.52},
  U:{mouth:'M-14-3Q0-10 14-3Q18 21 0 24Q-18 21-14-3Z',lower:'M-13 0Q0 25 13 0Q0 20-13 0Z',teeth:0,tongue:.3},
  M:{mouth:'M-28 2Q0 8 28 2Q0 11-28 2Z',lower:'M-27 4Q0 12 27 4Q0 9-27 4Z',teeth:0,tongue:0},
  F:{mouth:'M-29-1Q0 4 29-1Q0 15-29-1Z',lower:'M-27 5Q0 16 27 5Q0 12-27 5Z',teeth:.98,tongue:0}
};
let lipTimer=null,blinkTimer=null;
function mouthFor(char){char=char.toLowerCase();if('aä'.includes(char))return'A';if('e'.includes(char))return'E';if('iyj'.includes(char))return'I';if('oö'.includes(char))return'O';if('uü'.includes(char))return'U';if('mbp'.includes(char))return'M';if('fvw'.includes(char))return'F';if('szßxckgtdnlrhq'.includes(char))return'E';return'REST'}
function visemesFor(text){const source=String(text).toLocaleLowerCase('de-DE'),result=[];for(let i=0;i<source.length;i++){const pair=source.slice(i,i+2),triple=source.slice(i,i+3);if(triple==='sch'){result.push('E','I');i+=2;continue}if(pair==='ch'){result.push('I','E');i++;continue}if(pair==='au'){result.push('A','O');i++;continue}if(pair==='ei'||pair==='ai'){result.push('A','I');i++;continue}if(pair==='eu'||pair==='äu'){result.push('O','I');i++;continue}if(pair==='ie'){result.push('I','I');i++;continue}const shape=mouthFor(source[i]);result.push(shape);if(/[,.!?;:]/.test(source[i]))result.push('REST','REST');else if(/\s/.test(source[i]))result.push('REST')}return result.length?result:['REST']}
function setMouth(shape){const rig=MOUTH_RIG[shape]||MOUTH_RIG.REST,mouth=$('#avatarMouth'),teeth=$('#avatarTeeth'),tongue=$('#avatarTongue'),lower=$('#avatarLowerLip'),stage=$('.avatar-stage');if(!mouth)return;mouth.setAttribute('d',rig.mouth);lower?.setAttribute('d',rig.lower);teeth?.setAttribute('opacity',rig.teeth);tongue?.setAttribute('opacity',rig.tongue);if(stage)stage.dataset.viseme=shape}
function startLipSync(text,audio=null){stopLipSync();const sequence=visemesFor(text),started=performance.now(),estimated=Math.max(1100,String(text).length*78/(selectedCharacter().speed||1));let previous=-1;const animate=()=>{if(!state.isSpeaking)return;const audioReady=audio&&Number.isFinite(audio.duration)&&audio.duration>0,progress=audioReady?Math.min(.999,audio.currentTime/audio.duration):((performance.now()-started)%estimated)/estimated,index=Math.min(sequence.length-1,Math.floor(progress*sequence.length));if(index!==previous){setMouth(sequence[index]);previous=index}lipTimer=requestAnimationFrame(animate)};lipTimer=requestAnimationFrame(animate)}
function stopLipSync(){if(lipTimer)cancelAnimationFrame(lipTimer);lipTimer=null;setMouth('REST')}
let avatarBehaviorTimer=null;
function setAvatarBehavior(kind='idle',duration=0){const stage=$('.avatar-stage');if(!stage)return;clearTimeout(avatarBehaviorTimer);stage.dataset.behavior=kind;if(duration){const factor=state.motion==='expressive'?1.2:(state.motion==='calm'?0.75:1);avatarBehaviorTimer=setTimeout(()=>{stage.dataset.behavior='idle'},duration*factor)}}
function inferAvatarBehavior(text){const value=String(text).toLocaleLowerCase('de-DE').trim();if(/sehr gut|hervorragend|geschafft|vollständig|abgeschlossen|bestanden|gratuliere|wunderbar/.test(value))return'celebrate';if(/^gut\b|gute idee|das klingt gut|gut, dann|richtig|super|fantastisch|einverstanden|genau|machen wir das so|passt gut/.test(value))return'success';if(/noch einmal|versuche|fehlt|nicht ganz|unvollständig|leider|korrig|verbess|bleiben wir/.test(value))return'encourage';if(/[?]$|was meinst|wie findest|möchtest du|kannst du|sollen wir/.test(value))return'explain';return'speaking'}
function setVoiceState(type,label){const el=$('#voiceState');if(!el)return;el.className=`voice-state ${type||''}`;el.querySelector('span').textContent=label;if(type==='thinking')setAvatarBehavior('thinking');else if(type==='listening')setAvatarBehavior('listening')}
function startBlinking(){const blink=()=>{const stage=$('.avatar-stage');if(stage){stage.classList.add('blinking');setTimeout(()=>stage.classList.remove('blinking'),140)}blinkTimer=setTimeout(blink,2200+Math.random()*3200)};blinkTimer=setTimeout(blink,1800)}
let currentTtsAudio=null,currentTtsController=null,ttsRequestId=0;
const ttsCache=new Map();
function selectedCharacter(){return CHARACTERS[state.character]||CHARACTERS.clara}
function personalizeTeacherLabels(root){if(!root)return;const name=selectedCharacter().name,old=/\b(?:Clara|Mia|Frau Weber|Lukas)\b/g;for(const el of [root,...root.querySelectorAll('*')])for(const node of el.childNodes)if(node.nodeType===3&&old.test(node.nodeValue||'')){old.lastIndex=0;node.nodeValue=node.nodeValue.replace(old,name)}}
function speechStarted(text,audio=null){const c=selectedCharacter();state.isSpeaking=true;$('.avatar-stage')?.classList.add('speaking');setVoiceState('speaking',`${c.name} konuşuyor`);setAvatarBehavior(inferAvatarBehavior(text));startLipSync(text,audio)}
function speechFinished(resume=true){const behavior=$('.avatar-stage')?.dataset.behavior;state.isSpeaking=false;$('.avatar-stage')?.classList.remove('speaking');stopLipSync();setVoiceState('',resume?'Sıra sende':`${selectedCharacter().name} hazır`);setAvatarBehavior(['success','celebrate'].includes(behavior)?behavior:'idle',['success','celebrate'].includes(behavior)?1350:0);if(resume&&state.continuousListening)setTimeout(()=>startRecognition(true),450)}
function stopSpeech(resume=false){ttsRequestId++;currentTtsController?.abort();currentTtsController=null;if(currentTtsAudio){currentTtsAudio.pause();currentTtsAudio.src='';currentTtsAudio=null}window.speechSynthesis?.cancel();speechFinished(resume)}
function systemSpeak(text,resume,id){return new Promise(resolve=>{if(id!==ttsRequestId)return resolve(false);if(!('speechSynthesis'in window)){speechFinished(resume);return resolve(false)}const u=new SpeechSynthesisUtterance(text),c=selectedCharacter();u.lang='de-DE';u.rate=c.speed;const voices=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('de'));u.voice=voices.find(v=>state.character==='lukas'&&/male|männ|stefan|markus|thomas/i.test(v.name))||voices[0]||null;u.onstart=()=>speechStarted(text);u.onend=u.onerror=()=>{if(id===ttsRequestId)speechFinished(resume);resolve(true)};speechSynthesis.speak(u)})}
async function speak(text,{resume=true}={}){if(!text)return false;state.lastSpeech=text;stopRecognition(false);stopSpeech(false);const id=ttsRequestId,c=selectedCharacter(),key=`hq2|${c.voice}|${c.speed}|${text}`;setVoiceState('thinking',`${c.name} sesi hazırlanıyor`);setAvatarBehavior(inferAvatarBehavior(text));try{currentTtsController=new AbortController();let blob=ttsCache.get(key);if(!blob){const r=await fetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,voice:c.voice,speed:c.speed}),signal:currentTtsController.signal});if(!r.ok)throw Error('tts');blob=await r.blob();ttsCache.set(key,blob);if(ttsCache.size>24)ttsCache.delete(ttsCache.keys().next().value)}if(id!==ttsRequestId)return false;const url=URL.createObjectURL(blob),audio=new Audio(url);audio.preload='auto';currentTtsAudio=audio;await new Promise((resolve,reject)=>{audio.onplay=()=>speechStarted(text,audio);audio.onended=resolve;audio.onerror=reject;audio.play().catch(reject)});URL.revokeObjectURL(url);if(id===ttsRequestId){currentTtsAudio=null;speechFinished(resume)}return true}catch(error){if(error?.name==='AbortError'||id!==ttsRequestId)return false;currentTtsController=null;return systemSpeak(text,resume,id)}}

function characterPortrait(c,id){return `<span class="character-portrait" style="--avatar-halo:${c.halo};--avatar-hair:${c.hair};--avatar-jacket:${c.jacket};--avatar-skin:${c.skin}"><i></i><b></b><em></em></span><span><b>${c.name}</b><small>${c.role}</small><em>${c.voice} · cihazda yerel</em></span><i class="character-check">✓</i>`}
function renderCharacterGrid(){const root=$('#characterGrid');if(!root)return;root.innerHTML=Object.entries(CHARACTERS).map(([id,c])=>`<button type="button" class="character-card ${id===state.character?'selected':''}" data-character-choice="${id}">${characterPortrait(c,id)}</button>`).join('')}
function ensureHeroAvatar(){const hero=$('.hero-portrait'),image=$('#tutorImage');if(!hero)return null;let clone=$('#heroAvatarRig');if(clone)return clone;const source=$('.avatar-stage .avatar-2d');if(!source)return null;clone=source.cloneNode(true);clone.id='heroAvatarRig';clone.classList.add('hero-avatar-rig');const idMap={};clone.querySelectorAll('[id]').forEach((el,i)=>{const old=el.id,next=`hero-${old}-${i}`;idMap[old]=next;el.id=next});clone.querySelectorAll('*').forEach(el=>{for(const attr of ['fill','stroke','filter','clip-path','mask','href','xlink:href']){const value=el.getAttribute(attr);if(!value)continue;let next=value;for(const [old,id] of Object.entries(idMap))next=next.replaceAll(`url(#${old})`,`url(#${id})`).replaceAll(`#${old}`,`#${id}`);if(next!==value)el.setAttribute(attr,next)}});hero.insertBefore(clone,image);image.hidden=true;return clone}
function applyCharacter(){const c=selectedCharacter(),stage=$('.avatar-stage');if(stage){stage.dataset.character=state.character;stage.dataset.motion=state.motion;stage.dataset.behavior='idle';stage.style.setProperty('--avatar-halo',c.halo);stage.style.setProperty('--avatar-hair',c.hair);stage.style.setProperty('--avatar-jacket',c.jacket);stage.style.setProperty('--avatar-skin',c.skin);stage.querySelector('.avatar-caption b').textContent=c.name;stage.querySelector('.avatar-caption span').textContent=c.role;stage.querySelector('svg').setAttribute('aria-label',`${c.name} ile konuşma pratiği`)}const hero=$('.hero-portrait');if(hero){hero.dataset.character=state.character;hero.style.setProperty('--avatar-halo',c.halo);hero.style.setProperty('--avatar-hair',c.hair);hero.style.setProperty('--avatar-jacket',c.jacket);hero.style.setProperty('--avatar-skin',c.skin);const preview=ensureHeroAvatar();if(preview)preview.setAttribute('aria-label',`2D Almanca öğretmeni ${c.name}`)}const image=$('#tutorImage');if(image)image.alt=`2D Almanca öğretmeni ${c.name}`;const heroCopy=$('.hero-copy>p');if(heroCopy)heroCopy.textContent=`${c.name} bugün seni telc B1 sözlü sınavının “Gemeinsam etwas planen” bölümüne hazırlayacak.`;if(!state.isSpeaking)setVoiceState('',`${c.name} hazır`);renderCharacterGrid()}
async function checkTts(){const s=$('#ttsStatus');if(s)s.textContent='Supertonic 3 başlatılıyor…';try{const r=await fetch('/api/tts/status');const d=await r.json();if(!r.ok)throw Error();if(s)s.textContent=`${d.engine} hazır · ${d.voices} yerel ses`;return true}catch{if(s)s.textContent='Yerel motor kapalı · sistem sesi kullanılacak';return false}}

const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
let recognition=null,recognizing=false,finalTranscript='',speechPauseTimer=null,suppressRecognitionSend=false;
function buildRecognition(continuous){const rec=new SR();rec.lang='de-DE';rec.interimResults=true;rec.continuous=continuous;rec.onstart=()=>{recognizing=true;finalTranscript='';$('#micBtn').classList.add('recording');setVoiceState('listening',continuous?'Seni dinliyorum · kesintisiz':'Seni dinliyorum · bırakınca gönder')};rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const part=e.results[i][0].transcript;if(e.results[i].isFinal)finalTranscript+=`${part} `;else interim+=part}$('#chatInput').value=(finalTranscript+interim).trim();if(continuous&&finalTranscript.trim()){clearTimeout(speechPauseTimer);speechPauseTimer=setTimeout(()=>stopRecognition(true),850)}};rec.onerror=e=>{recognizing=false;$('#micBtn').classList.remove('recording');if(e.error==='not-allowed'||e.error==='service-not-allowed'){state.continuousListening=false;updateMicUI();toast('Mikrofon izni verilmedi. Tarayıcı ayarlarından izin verin.')}else if(e.error!=='aborted'&&e.error!=='no-speech')toast('Ses anlaşılamadı; tekrar deneyin.')};rec.onend=()=>{recognizing=false;$('#micBtn').classList.remove('recording');const wasSuppressed=suppressRecognitionSend;suppressRecognitionSend=false;const text=wasSuppressed?'':(finalTranscript||$('#chatInput').value).trim();finalTranscript='';if(text){sendUser(text)}else if(state.continuousListening&&!state.isSpeaking&&!wasSuppressed){setVoiceState('','Ses bekleniyor');setTimeout(()=>startRecognition(true),400)}else setVoiceState('','Sıra sende')};return rec}
function startRecognition(continuous=false){if(!SR){toast('Bu tarayıcı ses tanımayı desteklemiyor. Mesaj yazarak devam edebilirsiniz.');return}if(recognizing||state.isSpeaking||$('#chatForm').classList.contains('busy'))return;window.speechSynthesis?.cancel();suppressRecognitionSend=false;recognition=buildRecognition(continuous);try{recognition.start()}catch{}}
function stopRecognition(sendAfter=true){clearTimeout(speechPauseTimer);if(!recognizing||!recognition)return;suppressRecognitionSend=!sendAfter;if(!sendAfter)finalTranscript='';try{recognition.stop()}catch{}}
function updateMicUI(){const on=state.continuousListening;$$('[data-mic-mode]').forEach(b=>b.classList.toggle('active',b.dataset.micMode===state.micMode));$('#micBtn').classList.toggle('continuous-on',on);$('#micBtn').setAttribute('aria-label',state.micMode==='hold'?'Konuşmak için basılı tut':on?'Kesintisiz dinlemeyi kapat':'Kesintisiz dinlemeyi başlat');$('#micBtn small').textContent=state.micMode==='hold'?'Basılı tut ve konuş':on?'Dinleme açık · kapat':'Kesintisiz başlat'}
function setupMic(){const mic=$('#micBtn');$$('[data-mic-mode]').forEach(b=>b.onclick=()=>{state.micMode=b.dataset.micMode;if(state.micMode==='hold'&&state.continuousListening){state.continuousListening=false;stopRecognition(false)}updateMicUI()});const pressStart=e=>{if(state.micMode!=='hold')return;e.preventDefault();mic.setPointerCapture?.(e.pointerId);startRecognition(false)};const pressEnd=e=>{if(state.micMode!=='hold')return;e.preventDefault();stopRecognition(true)};mic.addEventListener('pointerdown',pressStart);mic.addEventListener('pointerup',pressEnd);mic.addEventListener('pointercancel',pressEnd);mic.addEventListener('pointerleave',e=>{if(e.buttons)pressEnd(e)});mic.onclick=e=>{if(state.micMode!=='continuous')return;e.preventDefault();state.continuousListening=!state.continuousListening;updateMicUI();if(state.continuousListening)startRecognition(true);else{stopRecognition(false);setVoiceState('','Sıra sende')}};updateMicUI()}
function startSession(){if(!state.started){state.started=true;state.timer=setInterval(()=>{state.seconds++;$('#sessionTimer').textContent=`${String(Math.floor(state.seconds/60)).padStart(2,'0')}:${String(state.seconds%60).padStart(2,'0')}`},1000)}beginSourceExam()}

