function scenePerson(x,y,shirt='#28477d',scale=1,arm='down'){const arms=arm==='point'?`<path d="M ${x+13*scale} ${y+34*scale} Q ${x+38*scale} ${y+24*scale} ${x+50*scale} ${y+10*scale}"/> <circle cx="${x+52*scale}" cy="${y+8*scale}" r="${4*scale}"/>`:`<path d="M ${x-12*scale} ${y+35*scale} L ${x-23*scale} ${y+62*scale} M ${x+12*scale} ${y+35*scale} L ${x+23*scale} ${y+62*scale}"/>`;return `<g stroke="#653f35" stroke-width="${6*scale}" stroke-linecap="round" fill="none"><path d="M ${x-7*scale} ${y+74*scale} L ${x-10*scale} ${y+105*scale} M ${x+7*scale} ${y+74*scale} L ${x+12*scale} ${y+105*scale}"/>${arms}</g><path d="M ${x-18*scale} ${y+30*scale} Q ${x} ${y+20*scale} ${x+18*scale} ${y+30*scale} L ${x+14*scale} ${y+78*scale} L ${x-14*scale} ${y+78*scale}Z" fill="${shirt}"/><circle cx="${x}" cy="${y+12*scale}" r="${16*scale}" fill="#efb48f"/><path d="M ${x-15*scale} ${y+9*scale} Q ${x-7*scale} ${y-12*scale} ${x+13*scale} ${y+2*scale} L ${x+15*scale} ${y+10*scale}" fill="#5c382b"/><circle cx="${x-5*scale}" cy="${y+12*scale}" r="${1.5*scale}" fill="#26324a"/><circle cx="${x+5*scale}" cy="${y+12*scale}" r="${1.5*scale}" fill="#26324a"/></g>`}
