const WORD_SCENE_FILES={scenes:'assets/goethe-word-scenes-v1.png',actions:'assets/goethe-word-actions-v1.png',places:'assets/goethe-word-places-v1.png'},WORD_SCENE_POSITIONS=[1,25.5,50,74.5,99];
function wordVisual(card,compact=false){const scene=semanticWordScene(card),uniqueImage=state.wordImageManifest[card.id],[atlas,index]=WORD_SCENES[scene]||WORD_SCENES.study,column=index%5,row=Math.floor(index/5),x=WORD_SCENE_POSITIONS[column],y=WORD_SCENE_POSITIONS[row],description=`${card.word}: ${card.example}`;if(uniqueImage)return `<span class="word-scene-art unique${compact?' compact':''}" role="img" aria-label="${escapeHtml(description)}" data-scene="unique" style="--scene-image:url('${escapeHtml(uniqueImage)}')"></span>`;return `<span class="word-scene-art${compact?' compact':''}" role="img" aria-label="${escapeHtml(description)}" data-scene="${scene}" style="--scene-image:url('${WORD_SCENE_FILES[atlas]}');--scene-x:${x}%;--scene-y:${y}%"></span>`}
function translationKey(card){return `v4:${state.uiLang}:${card.id}`}
function cachedTranslation(card){const language=state.uiLang==='tr'?'tr':'en',packed=state.wordPacks[language]?.[card.id];if(Array.isArray(packed))return {meaning:packed[0],exampleTranslation:packed[1]};return packed?.meaning&&packed?.exampleTranslation?packed:null}
function wordBackCopy(){return state.uiLang==='tr'?{meaning:'KELİME ANLAMI',sentence:'CÜMLE ÇEVİRİSİ',hint:'Görsele dönmek için dokun'}:{meaning:'WORD MEANING',sentence:'SENTENCE TRANSLATION',hint:'Tap to return to the image'}}
function renderWords(){const card=currentWord(),parts=splitWord(card.word),translation=cachedTranslation(card),copy=wordCopy(),back=wordBackCopy(),missing=state.uiLang==='tr'?'Çeviri paketi hazırlanıyor.':'Translation pack is being prepared.';$('#wordVisual').innerHTML=`<div class="word-flip${state.wordFlipped?' is-flipped':''}" data-word-flip><div class="word-flip-inner"><div class="word-flip-face word-flip-front">${wordVisual(card)}<span>${state.uiLang==='tr'?'Anlamı görmek için görsele dokun':'Tap the image to see the meaning'}</span></div><div class="word-flip-face word-flip-back"><small>${back.meaning}</small><strong>${escapeHtml(translation?.meaning||missing)}</strong><small>${back.sentence}</small><p>${escapeHtml(translation?.exampleTranslation||'')}</p><em>${back.hint}</em></div></div></div>`;$('#wordArticle').textContent=parts.article;$('#wordArticle').style.visibility=parts.article?'visible':'hidden';$('#wordGerman').textContent=parts.main;$('#wordForms').textContent=card.forms&&card.forms!==card.word?card.forms:'';$('#wordExample').textContent=card.example;$('#wordSource').textContent=`${card.category} · PDF S. ${card.sourcePage}`;$('#wordAudio').textContent=`▶ ${copy.listen}`;$('#wordTotal').textContent=state.words.length.toLocaleString(state.uiLang);$('#wordTodayProgress').textContent=`${(state.word%state.wordSettings.count)+1} / ${state.wordSettings.count}`;$('#wordTranslation').hidden=true;$('#flashcard').classList.toggle('revealed',state.wordFlipped)}
async function speakWordCard(card=currentWord()){await speak(card.word,{resume:false});await new Promise(r=>setTimeout(r,850));await speak(card.example,{resume:false})}
async function translateWord(card=currentWord()){return cachedTranslation(card)||{meaning:state.uiLang==='tr'?'Çeviri paketi hazırlanıyor.':'Translation pack is being prepared.',exampleTranslation:''}}
function revealCurrentWord(){state.wordFlipped=!state.wordFlipped;renderWords()}
function applyWordLanguage(){if(!$('#wordPageTitle'))return;const copy=wordCopy();$('#wordPageTitle').textContent=copy.title;$('#wordPageText').textContent=copy.text;$('#wordLibraryLabel').textContent=copy.library;$('#wordProgressLabel').textContent=copy.today;$('#startQuickReview').textContent=`✦ ${copy.quick}`;$('#quickReviewSwipeHint').textContent=copy.hint;if(state.view==='words')renderWords()}
function saveWordSettings(){state.wordSettings.enabled=$('#quickReviewEnabled').checked;state.wordSettings.count=Number($('#dailyWordCount').value)||5;localStorage.setItem(WORD_PREF_KEY,JSON.stringify(state.wordSettings));$('#wordSettingsDialog').close();renderWords();toast(state.wordSettings.enabled?'Günlük hızlı tekrar açıldı.':'Günlük hızlı tekrar kapatıldı.')}
function openWordSettings(){ $('#quickReviewEnabled').checked=state.wordSettings.enabled;$('#dailyWordCount').value=String(state.wordSettings.count);$('#wordSettingsDialog').showModal() }
function quickMotivation(){return WORD_MOTIVATION[state.uiLang]||wordCopy().done}
function openQuickReview(force=false){if(!state.words.length||!force&&(!state.wordSettings.enabled||state.view!=='home'||state.started||state.exam||state.oral.part))return;const count=Math.min(state.wordSettings.count,state.words.length),start=state.word%state.words.length;state.quickReview={items:Array.from({length:count},(_,i)=>state.words[(start+i)%state.words.length]),index:0,flipped:false,lastShown:Date.now()};$('#quickReview').hidden=false;document.body.classList.add('quick-review-open');renderQuickReview()}
function closeQuickReview(){window.speechSynthesis?.cancel();$('#quickReview').hidden=true;document.body.classList.remove('quick-review-open')}
function renderQuickReview(){const review=state.quickReview,card=review.items[review.index];if(!card)return;const parts=splitWord(card.word),translation=cachedTranslation(card),copy=wordCopy();$('#quickReviewEyebrow').textContent=`${copy.today} · ${review.items.length} ${state.uiLang==='de'?'WÖRTER':'KELİME'}`;$('#quickReviewCounter').textContent=`${review.index+1} / ${review.items.length}`;$('#quickReviewProgress').style.width=`${(review.index+1)/review.items.length*100}%`;$('#quickReviewPrev').disabled=review.index===0;$('#quickReviewCard').innerHTML=`<article class="quick-word-card ${review.flipped?'flipped':''}" data-quick-audio>${wordVisual(card,true)}<small>${escapeHtml(card.category)}</small><span>${escapeHtml(parts.article)}</span><h2>${escapeHtml(parts.main)}</h2><p>${escapeHtml(card.example)}</p><button data-quick-flip>${escapeHtml(copy.reveal)}</button><div class="quick-word-translation" ${review.flipped?'':'hidden'}><b>${escapeHtml(translation?.meaning||copy.loading)}</b><p>${escapeHtml(translation?.exampleTranslation||'')}</p></div></article>`;if(review.flipped&&!translation)translateQuickWord(card)}
async function translateQuickWord(card){const value=await translateWord(card);if(state.quickReview.items[state.quickReview.index]?.id!==card.id)return;const box=$('.quick-word-translation');if(box){box.querySelector('b').textContent=value.meaning;box.querySelector('p').textContent=value.exampleTranslation}}
function flipQuickReview(){state.quickReview.flipped=true;renderQuickReview()}
function moveQuickReview(direction){const review=state.quickReview;if(direction<0&&review.index>0){review.index--;review.flipped=false;return renderQuickReview()}if(direction>0&&review.index<review.items.length-1){review.index++;review.flipped=false;state.word=(state.word+1)%state.words.length;return renderQuickReview()}if(direction>0){$('#quickReviewCard').innerHTML=`<div class="quick-review-done"><span>✓</span><h2>${escapeHtml(quickMotivation())}</h2></div>`;$('#quickReviewNext').disabled=true;setTimeout(closeQuickReview,1900)}}
function renderGrammar(){$('#grammarGrid').innerHTML=GRAMMAR.map(g=>`<article class="grammar-card"><small>B1 · KONU ${GRAMMAR.indexOf(g)+1}</small><h3>${g[0]}</h3><p>${g[1]}</p><blockquote>${g[2]}</blockquote><button data-go="practice">Clara ile uygula →</button></article>`).join('')}
function renderLibrary(){const list=$('#libraryList');list.innerHTML=state.library.length?state.library.map(f=>`<article class="file-row"><span>${escapeHtml(f.type.toUpperCase())}</span><div><b>${escapeHtml(f.name)}</b><small>${escapeHtml(f.size)} · ${f.chars?`${f.chars.toLocaleString('tr-TR')} karakter · ${f.themes||0} tema`:'hazır'}</small></div><em>✓ Kaynak kilitli</em></article>`).join(''):'<article class="file-row"><span>PDF</span><div><b>Henüz sınav kaynağı yüklenmedi</b><small>A/B veya Partner konuşmaları bulunan PDF’nizi ekleyin.</small></div><em>Bekliyor</em></article>'}
async function refreshLibrary(){try{const r=await fetch('/api/library');if(r.ok)state.library=await r.json()}catch{}renderLibrary()}
async function uploadFiles(files){for(const file of files){toast(`${file.name} içindeki temalar ayrılıyor…`);const base64=await new Promise((ok,fail)=>{const r=new FileReader();r.onload=()=>ok(r.result.split(',')[1]);r.onerror=fail;r.readAsDataURL(file)});try{const res=await fetch('/api/library',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,type:file.name.split('.').pop(),size:file.size,data:base64})});const item=await res.json();if(!res.ok)throw new Error(item.error);toast(`${item.themes} sınav teması kaynağa bağlandı.`)}catch(error){toast(error.message||'PDF işlenemedi.')}}await refreshLibrary()}
const formatBytes=n=>n<1024?`${n} B`:`${(n/1024/1024).toFixed(1)} MB`;
function renderSkills(){const skills=[['Akıcılık',74],['Kelime çeşitliliği',68],['Gramer doğruluğu',71],['Telaffuz',82],['Etkileşim',78]];$('#skillBars').innerHTML=skills.map(([n,v])=>`<div class="skill-row"><span>${n}</span><i><u style="width:${v}%"></u></i><b>${v}</b></div>`).join('')}

function bind(){
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]'),go=e.target.closest('[data-go]'),part=e.target.closest('[data-exam-part]');if(nav)navigate(nav.dataset.view);if(go)navigate(go.dataset.go);if(part){const id=part.dataset.examPart;if(id==='planen'){state.mode='planen';navigate('practice')}else if(id==='vorstellen'||id==='bild')openOralPart(id);else toast('Für diesen Teil wird noch eine passende PDF-Quelle benötigt.')}});
  $('.mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');
  $('#themeCatalog').onclick=e=>{const card=e.target.closest('[data-theme-id]');if(card)selectTheme(card.dataset.themeId)};
  $('#themeSearch').oninput=e=>renderThemeCatalog(e.target.value);
  $('#themeStartBtn').onclick=()=>beginSourceExam();
  $('#changeTheme').onclick=()=>{state.continuousListening=false;stopRecognition(false);stopSpeech(false);state.exam=null;$('#practiceLayout').hidden=true;$('#themePicker').hidden=false;$('#themeStartBtn').hidden=true;$('#pageTitle').textContent=t('chooseTheme');window.scrollTo({top:0,behavior:'smooth'})};
  $('#chatForm').onsubmit=e=>{e.preventDefault();sendUser($('#chatInput').value)};
  $('#repeatBtn').onclick=()=>speak(state.lastSpeech);
  $('#endCall').onclick=()=>{state.continuousListening=false;state.exam=null;stopRecognition(false);stopSpeech(false);clearInterval(state.timer);state.timer=null;state.started=false;toast('Sitzung gespeichert.');navigate('progress')};
  $('#oralApp').onclick=e=>{const back=e.target.closest('[data-oral-back]'),mode=e.target.closest('[data-oral-mode]'),info=e.target.closest('[data-oral-info]'),picture=e.target.closest('[data-picture-index]'),submit=e.target.closest('[data-oral-submit]'),mic=e.target.closest('[data-oral-mic]');if(back){stopOralRecording();return navigate('exam')}if(mode){stopOralRecording();state.oral.mode=mode.dataset.oralMode;state.oral.step=0;state.oral.lastFeedback=null;state.oral.result=null;state.oral.draft='';renderOral();const steps=state.oral.part==='bild'?BILD_STEPS:VORSTELLEN_STEPS;speak(state.oral.mode==='exam'?(state.oral.part==='bild'?'Beschreiben Sie bitte das Bild vollständig.':'Stellen Sie sich bitte vollständig vor.'):steps[0][1]);return}if(info){state.oral.showInfo=!state.oral.showInfo;renderOral();return}if(picture)return selectPicture(picture.dataset.pictureIndex);if(submit)return handleOralSubmit();if(mic)return recordOral()};
  $('#oralApp').oninput=e=>{if(e.target.id==='oralTranscript'){state.oral.draft=e.target.value;if(state.oral.mode==='exam')updateVorstellenChecklist(e.target.value)}};
  $('.listen-greeting').onclick=()=>speak(`Hallo ${currentStudent()?.name||''}! Bereit für heute?`);$('.listen-tip').onclick=()=>speak('Was meinst du dazu?');
  $('#flashcard').onclick=e=>{if(e.target.closest('button')||e.target.closest('#wordVisual'))return;speakWordCard()};$('#flashcard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();speakWordCard()}};
  $('#wordVisual').onclick=e=>{e.stopPropagation();revealCurrentWord()};$('#wordAudio').onclick=e=>{e.stopPropagation();speakWordCard()};$('#revealWord').hidden=true;$$('[data-rate]').forEach(b=>b.onclick=()=>{state.word=(state.word+1)%state.words.length;state.wordFlipped=false;renderWords();toast(b.dataset.rate==='good'?'Sehr gut!':'Die Karte wird wiederholt.')});
  $('#wordSettingsBtn').onclick=openWordSettings;$('#saveWordSettings').onclick=saveWordSettings;$('#startQuickReview').onclick=()=>openQuickReview(true);$('#closeQuickReview').onclick=closeQuickReview;$('#quickReviewPrev').onclick=()=>moveQuickReview(-1);$('#quickReviewNext').onclick=()=>moveQuickReview(1);$('#quickReviewCard').onclick=e=>{if(e.target.closest('[data-quick-flip]'))return flipQuickReview();if(e.target.closest('[data-quick-audio]'))speakWordCard(state.quickReview.items[state.quickReview.index])};let quickTouchX=0;$('#quickReviewCard').addEventListener('touchstart',e=>quickTouchX=e.changedTouches[0].clientX,{passive:true});$('#quickReviewCard').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-quickTouchX;if(Math.abs(dx)>45)moveQuickReview(dx<0?1:-1)},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.wordSettings.enabled&&Date.now()-state.quickReview.lastShown>60000)setTimeout(()=>openQuickReview(),450)});
  $('#fileUpload').onchange=e=>uploadFiles([...e.target.files]);
  $('#settingsBtn').onclick=()=>{$('#appLanguage').value=state.uiLang;$('#ollamaUrl').value=state.settings.url;$('#modelName').value=state.settings.model;$('#avatarMotion').value=state.motion;renderCharacterGrid();$('#settingsDialog').showModal();checkTts()};
  $('#characterGrid').onclick=e=>{const card=e.target.closest('[data-character-choice]');if(!card)return;state.character=card.dataset.characterChoice;applyCharacter();personalizeTeacherLabels($('#taskBrief'))};
  $('#avatarMotion').onchange=e=>{state.motion=e.target.value;applyCharacter();setAvatarBehavior('celebrate',1600)};
  $('#previewVoice').onclick=()=>speak(`Sehr gut, ${currentStudent()?.name||''}! Das ist eine gute Idee. Wir können heute gemeinsam Deutsch üben.`,{resume:false});
  $('#testVoice').onclick=checkTts;
  $('#profileBtn').onclick=openProfileDialog;
  $('#profileSelect').onchange=e=>{const s=studentProfiles.find(x=>x.id===e.target.value);if(!s)return;profileDraftId=s.id;localStorage.setItem(CURRENT_PROFILE_KEY,s.id);fillProfileForm(s)};
  $('#newProfileBtn').onclick=()=>{profileDraftId=null;$('#profileSelect').value='';fillProfileForm(null);$('#studentName').focus()};
  $('#saveProfile').onclick=saveProfileFromForm;
  $('#partnerVisibility').onclick=()=>{partnerStore.visible=!partnerStore.visible;savePartnerStore();updatePartnerVisibility();toast(partnerStore.visible?'Profilin partner aramalarında görünür.':'Partner arama görünürlüğün kapatıldı.')};
  $$('[data-partner-tab]').forEach(b=>b.onclick=()=>setPartnerTab(b.dataset.partnerTab));
  ['partnerSearch','partnerLevel','partnerGoal','partnerExam','partnerLanguage'].forEach(id=>{$(`#${id}`).addEventListener(id==='partnerSearch'?'input':'change',renderPartnerDiscovery)});
  $('#clearPartnerFilters').onclick=()=>{$('#partnerSearch').value='';$('#partnerLevel').value='';$('#partnerGoal').value='';$('#partnerExam').value='';$('#partnerLanguage').value='';renderPartnerDiscovery()};
  $('#sendPartnerChat').onclick=sendPartnerChat;$('#partnerChatInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();sendPartnerChat()}};
  $('#createGroupBtn').onclick=openGroupDialog;$('#createGroupFromFriends').onclick=openGroupDialog;$('#saveGroup').onclick=saveGroup;
  document.addEventListener('click',e=>{const profile=e.target.closest('[data-partner-profile]'),request=e.target.closest('[data-partner-request]'),chat=e.target.closest('[data-partner-chat]'),practice=e.target.closest('[data-partner-practice]'),audio=e.target.closest('[data-partner-audio]'),video=e.target.closest('[data-partner-video]'),report=e.target.closest('[data-partner-report]'),block=e.target.closest('[data-partner-block]'),role=e.target.closest('[data-room-role]'),start=e.target.closest('[data-room-start]'),send=e.target.closest('[data-room-send]'),hint=e.target.closest('[data-room-hint]'),media=e.target.closest('[data-room-media]'),finish=e.target.closest('[data-room-finish]'),close=e.target.closest('[data-room-close]');if(profile)return openPartnerProfile(profile.dataset.partnerProfile);if(request)return addFriend(request.dataset.partnerRequest);if(chat)return openPartnerChat(chat.dataset.partnerChat);if(practice)return openPartnerRoom(practice.dataset.partnerPractice);if(audio){openPartnerRoom(audio.dataset.partnerAudio,'audio');return startPartnerMedia('audio')}if(video){openPartnerRoom(video.dataset.partnerVideo,'video');return startPartnerMedia('video')}if(report)return reportPartner(report.dataset.partnerReport);if(block)return blockPartner(block.dataset.partnerBlock);if(role){partnerStore.room.userRole=role.dataset.roomRole;return renderPartnerRoom()}if(start)return startRoom();if(send)return roomSend();if(hint)return showRoomHint();if(media)return startPartnerMedia(media.dataset.roomMedia);if(finish)return finishPartnerRoom();if(close){partnerMediaStream?.getTracks().forEach(x=>x.stop());partnerMediaStream=null;partnerStore.room=null;$('#partnerRoom').hidden=true;return setPartnerTab('friends')}});
  $('#partnerRoom').onchange=e=>{if(e.target.id==='roomThemeSelect'){partnerStore.room.themeId=e.target.value;partnerStore.room.taskIndex=0;partnerStore.room.turns=[];renderPartnerRoom()}};
  $('#testModel').onclick=async()=>{const s=$('#modelStatus');s.textContent='Verbindung wird geprüft…';try{const r=await fetch('/api/health',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ollamaUrl:$('#ollamaUrl').value,model:$('#modelName').value})});const d=await r.json();s.textContent=d.ok?`${d.model} bereit`:'Modell nicht gefunden'}catch{s.textContent='Lokaler Dienst ist nicht erreichbar'}};
  $('#saveSettings').onclick=()=>{state.uiLang=$('#appLanguage').value;state.motion=$('#avatarMotion').value;state.settings={url:$('#ollamaUrl').value.replace(/\/$/,''),model:$('#modelName').value};localStorage.setItem('appLanguage',state.uiLang);localStorage.setItem('ollamaUrl',state.settings.url);localStorage.setItem('modelName',state.settings.model);localStorage.setItem('teacherCharacter',state.character);localStorage.setItem('avatarMotion',state.motion);applyLanguage();applyCharacter();toast('Avatar, hareket ve ses ayarları kaydedildi.')};
  setupMic();startBlinking();refreshLibrary();loadThemes();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('/sw.js').catch(()=>{})
}

loadStudentProfiles();loadPartnerStore();loadWordTranslations();renderWeek();renderModes();renderTask();renderWords();renderGrammar();renderLibrary();renderSkills();bind();applyLanguage();applyStudentUI();applyCharacter();renderPartnerHub();loadWordList();
